//! Shared helpers for replaying `fixtures/valkey_sequence.json` (generated by
//! `fixtures/gen_valkey.py` from the Python connector).

#![allow(dead_code)]

use std::collections::BTreeMap;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

use meerschaum_api::traits::{DataQuery, DateBound, PipesKeysQuery, PluginRecord, SyncOptions};
use meerschaum_core::users::User;
use meerschaum_core::{Map, Pipe, Value};
use meerschaum_kernel::frame::{Column, ColumnData, values_to_series};
use meerschaum_kernel::value::{Value as KValue, parse_datetime_value};
use meerschaum_kernel::{Decimal, Frame};
use meerschaum_valkey::ValkeyConnector;
use serde_json::{Value as J, json};

/// The fixture.
pub fn fixture() -> J {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/valkey_sequence.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture")).expect("json")
}

/// A JSON value (untagged) as a core value.
pub fn core(j: &J) -> Value {
    meerschaum_api::pipe_ops::json_to_core(&untag(j))
}

/// Replace tagged scalars by their plain JSON form (datetimes as ISO strings).
pub fn untag(j: &J) -> J {
    match j {
        J::Object(o) if o.contains_key("t") => match o["t"].as_str() {
            Some("na" | "nan" | "nat") => J::Null,
            _ => o.get("v").cloned().unwrap_or(J::Null),
        },
        J::Object(o) => J::Object(o.iter().map(|(k, v)| (k.clone(), untag(v))).collect()),
        J::Array(a) => J::Array(a.iter().map(untag).collect()),
        other => other.clone(),
    }
}

/// A tagged JSON value as a kernel value.
pub fn kvalue(j: &J) -> KValue {
    match j {
        J::Null => KValue::Null,
        J::Bool(b) => KValue::Bool(*b),
        J::Number(n) => match n.as_i64() {
            Some(i) => KValue::Int(i),
            None => KValue::Float(n.as_f64().unwrap_or(f64::NAN)),
        },
        J::String(s) => KValue::Str(s.clone()),
        J::Object(o) if o.contains_key("t") => {
            let v = o.get("v").and_then(|v| v.as_str()).unwrap_or("");
            match o["t"].as_str().unwrap_or("") {
                "na" => KValue::NA,
                "nan" => KValue::Float(f64::NAN),
                "nat" => KValue::NaT,
                "dt" => parse_datetime_value(v)
                    .map(KValue::Datetime)
                    .unwrap_or(KValue::Null),
                "dec" => Decimal::parse(v)
                    .map(KValue::Decimal)
                    .unwrap_or(KValue::Null),
                "uuid" => uuid::Uuid::parse_str(v)
                    .map(KValue::Uuid)
                    .unwrap_or(KValue::Null),
                _ => KValue::Str(v.to_string()),
            }
        }
        other => KValue::Json(untag(other)),
    }
}

/// A kernel value as the generator's tagged JSON.
pub fn tag(v: &KValue) -> J {
    match v {
        v if v.is_na() => J::Null,
        KValue::Bool(b) => J::Bool(*b),
        KValue::Int(i) => json!(i),
        KValue::Float(f) => json!(f),
        KValue::Str(s) => J::String(s.clone()),
        KValue::Datetime(d) => json!({"t": "dt", "v": d.isoformat()}),
        KValue::Decimal(d) => json!({"t": "dec", "v": d.to_sci_string()}),
        KValue::Uuid(u) => json!({"t": "uuid", "v": u.to_string()}),
        KValue::Json(j) => j.clone(),
        other => J::String(other.py_str()),
    }
}

/// Normalize nulls (`None`, `NA`, `NaN`, `NaT`) for comparisons.
pub fn norm(j: &J) -> J {
    match j {
        J::Object(o)
            if matches!(
                o.get("t").and_then(|t| t.as_str()),
                Some("na" | "nan" | "nat")
            ) =>
        {
            J::Null
        }
        J::Object(o) => J::Object(o.iter().map(|(k, v)| (k.clone(), norm(v))).collect()),
        J::Array(a) => J::Array(a.iter().map(norm).collect()),
        J::Number(n) if n.as_f64().is_some_and(|f| f.fract() == 0.0) && n.as_i64().is_none() => {
            json!(n.as_f64().unwrap() as i64)
        }
        other => other.clone(),
    }
}

/// Rebuild a pipe from the generator's `__pipe__` encoding.
pub fn pipe(j: &J) -> Pipe {
    let p = &j["__pipe__"];
    let mut b = Pipe::builder(
        p["connector_keys"].as_str().unwrap(),
        p["metric_key"].as_str().unwrap(),
    )
    .location(p["location_key"].as_str())
    .instance(p["instance_keys"].as_str().unwrap())
    .kwarg("temporary", p["temporary"].as_bool().unwrap_or(false));
    if let Value::Map(params) = core(&p["parameters"]) {
        b = b.parameters(params);
    }
    b.build().expect("pipe")
}

/// Rebuild a user.
pub fn user(j: &J) -> User {
    let u = &j["__user__"];
    let s = |k: &str| u[k].as_str().map(String::from);
    let mut user = User::new(u["username"].as_str().unwrap(), u["password"].as_str());
    user.email = s("email");
    user.user_type = s("type");
    user.attributes = core(&u["attributes"]).as_map().cloned();
    user.user_id = match &u["user_id"] {
        J::Null => None,
        other => Some(core(other)),
    };
    user.password_hash = s("password_hash");
    user
}

/// Rebuild a plugin registration.
pub fn plugin(j: &J) -> PluginRecord {
    let p = &j["__plugin__"];
    PluginRecord {
        name: p["name"].as_str().unwrap().to_string(),
        version: p["version"].as_str().map(String::from),
        user_id: match &p["user_id"] {
            J::Null => None,
            other => Some(core(other)),
        },
        attributes: core(&p["attributes"]).as_map().cloned().unwrap_or_default(),
    }
}

/// Rebuild a DataFrame from `{"__df__": {columns, dtypes, data}}`.
pub fn frame(j: &J) -> Frame {
    let d = &j["__df__"];
    let mut cols = Vec::new();
    for name in d["columns"].as_array().unwrap() {
        let name = name.as_str().unwrap();
        let dtype = d["dtypes"][name].as_str().unwrap_or("object");
        let values: Vec<KValue> = d["data"][name]
            .as_array()
            .unwrap()
            .iter()
            .map(kvalue)
            .collect();
        let data = if dtype == "object" {
            ColumnData::Object(values)
        } else {
            let normalized: Vec<KValue> = values
                .iter()
                .map(|v| if v.is_na() { KValue::Null } else { v.clone() })
                .collect();
            match meerschaum_kernel::dtypes::polars_dtype_for_pandas(dtype)
                .and_then(|t| values_to_series(name, &normalized, &t))
            {
                Some(s) => ColumnData::Native(s),
                None => ColumnData::Object(values),
            }
        };
        cols.push(Column::new(name, data));
    }
    Frame::new(cols).expect("frame")
}

/// A frame as the generator's `__df__` encoding (columns and data; dtypes as the kernel reports).
pub fn frame_json(df: &Frame) -> J {
    let mut data = serde_json::Map::new();
    let mut dtypes = serde_json::Map::new();
    for c in df.columns() {
        dtypes.insert(c.name.clone(), J::String(c.data.dtype_str()));
        data.insert(
            c.name.clone(),
            J::Array(c.data.values().iter().map(tag).collect()),
        );
    }
    json!({"__df__": {"columns": df.names(), "dtypes": dtypes, "data": data}})
}

/// A deterministic user-ID factory (`fixtureid000`, `fixtureid001`, ...).
pub fn id_factory() -> Arc<dyn Fn() -> String + Send + Sync> {
    let n = Arc::new(AtomicUsize::new(0));
    Arc::new(move || format!("fixtureid{:03}", n.fetch_add(1, Ordering::SeqCst)))
}

fn arg<'a>(call: &'a J, ix: usize, name: &str) -> &'a J {
    if let Some(v) = call["args"].as_array().and_then(|a| a.get(ix)) {
        return v;
    }
    call["kwargs"].get(name).unwrap_or(&J::Null)
}

fn bound(j: &J) -> Option<DateBound> {
    match kvalue(j) {
        KValue::Datetime(d) => Some(DateBound::Datetime(d)),
        KValue::Int(i) => Some(DateBound::Int(i)),
        KValue::Str(s) if !s.is_empty() => DateBound::parse(&s),
        _ => None,
    }
}

fn strings(j: &J) -> Option<Vec<String>> {
    j.as_array().map(|a| {
        a.iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect()
    })
}

fn query(call: &J, offset: usize) -> DataQuery {
    let params = match core(arg(call, offset + 2, "params")) {
        Value::Map(m) => Some(m),
        _ => None,
    };
    DataQuery {
        select_columns: strings(&call["kwargs"]["select_columns"]),
        omit_columns: strings(&call["kwargs"]["omit_columns"]),
        begin: bound(arg(call, offset, "begin")),
        end: bound(arg(call, offset + 1, "end")),
        params,
        ..Default::default()
    }
}

fn tuple(t: meerschaum_core::SuccessTuple) -> J {
    json!([t.success, t.message])
}

fn opt_str(v: Option<String>) -> J {
    v.map(J::String).unwrap_or(J::Null)
}

fn core_json(v: &Value) -> J {
    serde_json::to_value(v).unwrap_or(J::Null)
}

/// Run one recorded call against the Rust connector and return its result in the fixture's
/// encoding.
pub async fn dispatch(conn: &ValkeyConnector, call: &J) -> J {
    use meerschaum_api::traits::InstanceConnector;
    let method = call["method"].as_str().unwrap();
    let p = || pipe(arg(call, 0, "pipe"));
    match method {
        "register_pipe" => tuple(conn.register_pipe(&p()).await),
        "get_pipe_id" => conn
            .get_pipe_id(&p())
            .await
            .unwrap()
            .map_or(J::Null, |i| json!(i)),
        "get_pipe_attributes" => core_json(&Value::Map(
            ValkeyConnector::get_pipe_attributes(conn, &p())
                .await
                .unwrap(),
        )),
        "edit_pipe" => tuple(ValkeyConnector::edit_pipe(conn, &p()).await),
        "pipe_exists" => json!(ValkeyConnector::pipe_exists(conn, &p()).await.unwrap()),
        "drop_pipe" => tuple(ValkeyConnector::drop_pipe(conn, &p()).await),
        "delete_pipe" => tuple(ValkeyConnector::delete_pipe(conn, &p()).await),
        "get_pipe_data" => match ValkeyConnector::get_pipe_data(conn, &p(), &query(call, 3))
            .await
            .unwrap()
        {
            Some(df) => frame_json(&df),
            None => J::Null,
        },
        "sync_pipe" => {
            let df = frame(arg(call, 1, "df"));
            let check_existing = call["kwargs"]["check_existing"].as_bool().unwrap_or(true);
            tuple(
                ValkeyConnector::sync_pipe(
                    conn,
                    &p(),
                    df,
                    &SyncOptions {
                        check_existing,
                        ..Default::default()
                    },
                )
                .await,
            )
        }
        "get_pipe_columns_types" => serde_json::to_value(
            ValkeyConnector::get_pipe_columns_types(conn, &p())
                .await
                .unwrap(),
        )
        .unwrap(),
        "clear_pipe" => tuple(ValkeyConnector::clear_pipe(conn, &p(), &query(call, 1)).await),
        "get_sync_time" => {
            let newest = call["kwargs"]["newest"].as_bool().unwrap_or(true);
            match ValkeyConnector::get_sync_time(conn, &p(), newest)
                .await
                .unwrap()
            {
                Some(DateBound::Datetime(d)) => json!({"t": "dt", "v": d.isoformat()}),
                Some(DateBound::Int(i)) => json!(i),
                None => J::Null,
            }
        }
        "get_pipe_rowcount" => ValkeyConnector::get_pipe_rowcount(conn, &p(), &query(call, 1))
            .await
            .unwrap()
            .map_or(J::Null, |n| json!(n)),
        "fetch_pipes_keys" => {
            let k = &call["kwargs"];
            let q = PipesKeysQuery {
                connector_keys: strings(&k["connector_keys"]).unwrap_or_default(),
                metric_keys: strings(&k["metric_keys"]).unwrap_or_default(),
                location_keys: k["location_keys"]
                    .as_array()
                    .map(|a| a.iter().map(|v| v.as_str().map(String::from)).collect())
                    .unwrap_or_default(),
                tags: strings(&k["tags"]).unwrap_or_default(),
                params: core(&k["params"]).as_map().cloned(),
            };
            J::Array(
                ValkeyConnector::fetch_pipes_keys(conn, &q)
                    .await
                    .unwrap()
                    .iter()
                    .map(|e| core_json(&Value::List(e.to_list())))
                    .collect(),
            )
        }
        "register_user" => {
            let mut u = user(arg(call, 0, "user"));
            tuple(conn.register_user(&mut u).await)
        }
        "get_user_id" => conn
            .get_user_id(&user(arg(call, 0, "user")))
            .await
            .unwrap()
            .map_or(J::Null, |v| core_json(&v)),
        "edit_user" => tuple(conn.edit_user(&user(arg(call, 0, "user"))).await),
        "get_user_attributes" => conn
            .get_user_attributes(&user(arg(call, 0, "user")))
            .await
            .unwrap()
            .map_or(J::Null, |m| core_json(&Value::Map(m))),
        "delete_user" => tuple(conn.delete_user(&user(arg(call, 0, "user"))).await),
        "get_users" => json!(conn.get_users().await.unwrap()),
        "get_user_password_hash" => opt_str(
            conn.get_user_password_hash(&user(arg(call, 0, "user")))
                .await
                .unwrap(),
        ),
        "get_user_type" => opt_str(
            conn.get_user_type(&user(arg(call, 0, "user")))
                .await
                .unwrap(),
        ),
        "register_plugin" => tuple(
            conn.register_plugin(&plugin(arg(call, 0, "plugin")), false)
                .await,
        ),
        "get_plugin_id" => opt_str(
            conn.get_plugin_id(&plugin(arg(call, 0, "plugin")))
                .await
                .unwrap(),
        ),
        "get_plugin_version" => opt_str(
            conn.get_plugin_version(&plugin(arg(call, 0, "plugin")))
                .await
                .unwrap(),
        ),
        "get_plugin_user_id" => conn
            .get_plugin_user_id(&plugin(arg(call, 0, "plugin")))
            .await
            .unwrap()
            .map_or(J::Null, |v| core_json(&v)),
        "get_plugin_username" => opt_str(
            conn.get_plugin_username(&plugin(arg(call, 0, "plugin")))
                .await
                .unwrap(),
        ),
        "get_plugin_attributes" => core_json(&Value::Map(
            conn.get_plugin_attributes(&plugin(arg(call, 0, "plugin")))
                .await
                .unwrap(),
        )),
        "delete_plugin" => tuple(conn.delete_plugin(&plugin(arg(call, 0, "plugin"))).await),
        "get_plugins" => {
            let user_id = match core(arg(call, 0, "user_id")) {
                Value::Null => None,
                other => Some(other),
            };
            let search = arg(call, 1, "search_term").as_str().map(String::from);
            json!(
                conn.get_plugins(user_id.as_ref(), search.as_deref())
                    .await
                    .unwrap()
            )
        }
        other => panic!("unhandled method {other}"),
    }
}

/// Dump every key with its type and value, as the generator does.
pub async fn dump(conn: &ValkeyConnector) -> BTreeMap<String, J> {
    let b = conn.backend();
    let mut out = BTreeMap::new();
    for key in b.keys("*").await.unwrap() {
        let typ = b.key_type(&key).await.unwrap();
        let value = match typ.as_str() {
            "string" => json!(b.get(&key).await.unwrap()),
            "zset" => J::Array(
                b.zrange(&key, 0, -1, false)
                    .await
                    .unwrap()
                    .into_iter()
                    .map(|(m, s)| json!([m, s]))
                    .collect(),
            ),
            "set" => {
                let mut m = b.smembers(&key).await.unwrap();
                m.sort();
                json!(m)
            }
            "list" => json!(b.lrange(&key, 0, -1).await.unwrap()),
            "hash" => {
                let m: serde_json::Map<String, J> = b
                    .hgetall(&key)
                    .await
                    .unwrap()
                    .into_iter()
                    .map(|(k, v)| (k, J::String(v)))
                    .collect();
                J::Object(m)
            }
            _ => J::Null,
        };
        out.insert(key, json!({"type": typ, "value": value}));
    }
    out
}

/// Compare a dataframe result: same columns, same values (nulls normalized). Rows are compared
/// in order, or as a multiset when the frame has no datetime ordering (`unordered`).
pub fn compare_frames(expected: &J, actual: &J, unordered: bool) -> Result<(), String> {
    let e = &expected["__df__"];
    let a = &actual["__df__"];
    if e["columns"] != a["columns"] {
        return Err(format!("columns {} != {}", e["columns"], a["columns"]));
    }
    let cols: Vec<String> = e["columns"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c.as_str().unwrap().to_string())
        .collect();
    let rows = |d: &J| -> Vec<Vec<J>> {
        let n = cols
            .first()
            .map_or(0, |c| d["data"][c].as_array().map_or(0, |a| a.len()));
        let mut out: Vec<Vec<J>> = (0..n)
            .map(|i| cols.iter().map(|c| norm(&d["data"][c][i])).collect())
            .collect();
        if unordered {
            out.sort_by_key(|r| serde_json::to_string(r).unwrap());
        }
        out
    };
    let (er, ar) = (rows(e), rows(a));
    if er != ar {
        return Err(format!(
            "rows differ:\n  expected {}\n  actual   {}",
            serde_json::to_string(&er).unwrap(),
            serde_json::to_string(&ar).unwrap()
        ));
    }
    Ok(())
}

/// Replay the fixture against `conn` (which must start empty) and return every mismatch.
pub async fn replay(conn: &ValkeyConnector) -> (Vec<String>, Vec<String>) {
    let fx = fixture();
    let mut mismatches = Vec::new();
    let mut notes = Vec::new();
    let (mut n_calls, mut n_keys) = (0usize, 0usize);
    for step in fx["steps"].as_array().unwrap() {
        let name = step["step"].as_str().unwrap();
        for (i, call) in step["calls"].as_array().unwrap().iter().enumerate() {
            let method = call["method"].as_str().unwrap();
            let actual = dispatch(conn, call).await;
            n_calls += 1;
            let expected = &call["result"];
            let ok = if expected.get("__df__").is_some() && actual.get("__df__").is_some() {
                let unordered = !expected["__df__"]["columns"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|c| {
                        let p = pipe(arg(call, 0, "pipe"));
                        p.column("datetime").as_deref() == c.as_str()
                    });
                match compare_frames(expected, &actual, unordered) {
                    Ok(()) => {
                        // Dtype names are compared loosely and reported as notes.
                        let ed = &expected["__df__"]["dtypes"];
                        let ad = &actual["__df__"]["dtypes"];
                        if let Some(o) = ed.as_object() {
                            for (c, t) in o {
                                let at = ad[c].as_str().unwrap_or("");
                                if !meerschaum_kernel::dtypes::are_dtypes_equal(
                                    t.as_str().unwrap_or(""),
                                    at,
                                ) {
                                    notes.push(format!(
                                        "{name}[{i}] {method}: dtype of '{c}' {t} vs {at}"
                                    ));
                                }
                            }
                        }
                        true
                    }
                    Err(e) => {
                        mismatches.push(format!("{name}[{i}] {method}: {e}"));
                        continue;
                    }
                }
            } else {
                norm(expected) == norm(&actual)
            };
            if !ok {
                mismatches.push(format!(
                    "{name}[{i}] {method}: expected {} got {}",
                    norm(expected),
                    norm(&actual)
                ));
            }
        }
        let state = dump(conn).await;
        let expected: BTreeMap<String, J> = step["state"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        n_keys += expected.len();
        for key in expected
            .keys()
            .chain(state.keys())
            .collect::<std::collections::BTreeSet<_>>()
        {
            let e = expected.get(key);
            let a = state.get(key);
            if e != a {
                mismatches.push(format!(
                    "{name} state '{key}': expected {} got {}",
                    e.map_or("<missing>".into(), |v| v.to_string()),
                    a.map_or("<missing>".into(), |v| v.to_string())
                ));
            }
        }
    }
    notes.push(format!(
        "replayed {n_calls} calls over {} steps, compared {n_keys} expected keys",
        fx["steps"].as_array().unwrap().len()
    ));
    (mismatches, notes)
}

/// Unused helper to keep `Map` imported for downstream helpers.
pub fn empty_map() -> Map {
    Map::new()
}
